package com.bulldozer_collective.modules.crm.api;

import lombok.Builder;
import org.jspecify.annotations.NonNull;
import org.jspecify.annotations.Nullable;

import java.time.Instant;
import java.util.Map;

/**
 * A landing page of the CRM's marketing tool.
 *
 * @param url         the page's address, generated by the CRM from {@code domain} and {@code slug}.
 * @param publishedAt when the page went live, or will — set when {@code state} is not a draft.
 * @param content     the page's content in the CRM's own format, passed through as is (HubSpot: {@code layoutSections}
 *                    and {@code widgets}). Only on a single page's read: absent from listings.
 */
@Builder
public record CrmLandingPage(@NonNull String id,
                             @NonNull String name,
                             @Nullable String slug,
                             @Nullable String domain,
                             @Nullable String url,
                             @Nullable String htmlTitle,
                             @Nullable String metaDescription,
                             @Nullable String language,
                             @Nullable String templatePath,
                             @NonNull CrmLandingPageState state,
                             @Nullable Instant publishedAt,
                             @Nullable Map<String, Object> content,
                             @Nullable Instant createdAt,
                             @Nullable Instant updatedAt) {
}
